def match_occurrences(g,pattern,vals=lambda v: v==0):
    H,W=len(g),len(g[0]); ph=max(r for r,_ in pattern)+1; pw=max(c for _,c in pattern)+1
    res=[]
    for i in range(H-ph+1):
        for j in range(W-pw+1):
            if all(vals(g[i+r][j+c]) for r,c in pattern):
                res.append((i,j))
    return res
