def rots(p):
    def rot(p): return [(c,-r) for r,c in p]
    ps=[p]; cur=p
    for _ in range(3):
        cur=rot(cur); ps.append(cur)
    mir=[(-r,c) for r,c in p]
    cur=mir; ps2=[mir]
    for _ in range(3):
        cur=rot(cur); ps2.append(cur)
    return ps+ps2
